function updateNode(items:TreeNode[],path:string,update:(node:TreeNode)=>TreeNode):TreeNode[]{return items.map(node=>node.path===path?update(node):node.children?{...node,children:updateNode(node.children,path,update)}:node);}
const BASE = 'http://127.0.0.1:11434';
const ignored = new Set(['node_modules','vendor','.git','dist','build','target','.next','coverage','storage','cache','.cache','.idea']);

async function scanProjectFiles(root:string,showHidden:boolean,onProgress:(files:number)=>void,cancelled:()=>boolean):Promise<number>{
  const pending=[root];let scanned=0;let folders=0;
  while(pending.length&&folders<30000){if(cancelled())return scanned;const path=pending.shift()!;folders++;const entries=await listDirectory(path,showHidden);for(const entry of entries){if(entry.is_dir){if(!ignored.has(entry.name)&&(showHidden||!entry.name.startsWith('.')))pending.push(entry.path);}else scanned++;}if(folders%20===0||pending.length===0){onProgress(scanned);await new Promise<void>(resolve=>window.setTimeout(resolve,0));}}
  if(folders>=30000)throw new Error('Proje çok fazla klasör içeriyor; tarama güvenlik sınırına ulaştı.');
  return scanned;
}

function prettySize(size: number) { return size > 1024 ** 3 ? `${(size/1024**3).toFixed(1)} GB` : size > 1024**2 ? `${(size/1024**2).toFixed(1)} MB` : `${(size/1024).toFixed(0)} KB`; }
function language(path: string) { const ext=path.split('.').pop()?.toLowerCase(); const map:Record<string,string>={tsx:'typescript',ts:'typescript',js:'javascript',jsx:'javascript',json:'json',md:'markdown',py:'python',rs:'rust',html:'html',css:'css',toml:'ini',yaml:'yaml',yml:'yaml',php:'php',go:'go',cs:'csharp',java:'java',cpp:'cpp',c:'c'}; return map[ext??'']??'plaintext'; }
function normalizeSearch(value:string){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').toLocaleLowerCase('tr');}
function sourcePriority(path:string){const p=normalizeSearch(path);const name=p.split(/[\\/]/).pop()??p;let score=0;if(/readme|composer\.json|package\.json|routes[\\/]web\.php/.test(p))score+=8;if(/index|home|welcome|landing|layout|app|main|page|header|footer|style|global/.test(name))score+=6;if(/resources[\\/]views|templates|pages|views/.test(p))score+=5;if(/\.(html?|blade\.php|vue|svelte)$/.test(p))score+=5;else if(/\.(css|scss|less)$/.test(p))score+=4;else if(/\.(php|jsx?|tsx?|json|md)$/.test(p))score+=2;return score;}
function isInsideWorkspace(workspace:string,path:string){const clean=(p:string)=>p.startsWith('\\\\?\\')||p.startsWith('//?/')?p.slice(4):p;const root=clean(workspace).replaceAll('/','\\').replace(/[\\]+$/,'').toLocaleLowerCase();const candidate=clean(path).replaceAll('/','\\').toLocaleLowerCase();return candidate===root||candidate.startsWith(`${root}\\`);}
function validBaselines(workspace:string,value:Record<string,string>){return Object.fromEntries(Object.entries(value).filter(([path,content])=>typeof content==='string'&&isInsideWorkspace(workspace,path)));}
function toRelative(workspace:string, path:string){const clean=(p:string)=>p.startsWith('\\\\?\\')||p.startsWith('//?/')?p.slice(4):p;const root=clean(workspace).replaceAll('\\','/').replace(/\/$/,'').toLowerCase()+'/';const cand=clean(path).replaceAll('\\','/');return cand.toLowerCase().startsWith(root)?cand.slice(root.length).replaceAll('/','\\'):clean(path).replaceAll('/','\\');}

